import React, { useState } from "react";
import "../styles/Chat.css";

const Chat = () => {

    const [input, setInput] = useState("");

    const [normalMessages, setNormalMessages] = useState([]);
    const [forgetMessages, setForgetMessages] = useState([]);

    const sendMessage = async () => {
        if (!input) return;

        const userMsg = { text: input, sender: "user" };

        setNormalMessages(prev => [...prev, userMsg]);
        setForgetMessages(prev => [...prev, userMsg]);

        const normalRes = await fetch("http://localhost:5000/api/chat/normal", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ message: input })
        });

        const forgetRes = await fetch("http://localhost:5000/api/chat/forget", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ message: input })
        });

        const normalData = await normalRes.json();
        const forgetData = await forgetRes.json();

        setNormalMessages(prev => [...prev, {
            text: normalData.reply,
            sender: "ai"
        }]);

        setForgetMessages(prev => [...prev, {
            text: forgetData.reply,
            sender: "ai"
        }]);

        setInput("");
    };

    return (
        <div className="chat-page">

            {/* LEFT SIDE */}
            <div className="chat-panel">

                <h2>Normal AI 🤖</h2>
                <p className="subtitle">Remembers everything</p>

                <div className="chat-box">
                    {normalMessages.map((msg, i) => (
                        <div key={i} className={msg.sender}>
                            {msg.text}
                        </div>
                    ))}
                </div>

            </div>

            {/* RIGHT SIDE */}
            <div className="chat-panel">

                <h2>Forgetting AI 🧠</h2>
                <p className="subtitle">Forgets intelligently</p>

                <div className="chat-box">
                    {forgetMessages.map((msg, i) => (
                        <div key={i} className={msg.sender}>
                            {msg.text}
                        </div>
                    ))}
                </div>

            </div>

            {/* INPUT (COMMON) */}
            <div className="input-container">
                <input
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="Ask something..."
                />
                <button onClick={sendMessage}>Send</button>
            </div>

        </div>
    );
};

export default Chat;
